EDITS = {'CHANGELOG.md': [('lines 1-1', "## [0.288.0] - a bank's deposit vault is lined with boxes\n", '## [0.289.0] - a score\'s alarm hooks\n\nThe walker, 2026-10-28, of score locations: "gameplay events or something that doesn\'t mean much for level factory but\nis part of what would trigger police coming or stuff like that for the dispatch layer"; "they could mean nothing,\nbut they could also be ingested/used by the gameplay layer of who is building this game" (the factory\'s roadmap 323).\n\n### Added\n- **`score_alarms.ALARM_FIXTURES`** (a new, Blender-free module): which fixture carries which event, keyed on the\n  slot\'s `role` or `species` -- a teller line\'s `alarm.panic_button` (silent), a vault door\'s `alarm.vault_door`\n  (audible), every deposit unit\'s `alarm.deposit_drilled` (silent), a drop safe\'s `alarm.safe_opened` (silent), an\n  ATM\'s `alarm.atm_tampered` (audible) and a cash cart\'s `score.cash_moved`. Data only: no heat, timer or response.\n- **`_Builder._score_alarms`**: one `alarm` marker per slot a row names, at the slot\'s centre, in the innermost room\n  on its storey that holds it, its event in `meta` (`event`, `audible`, `fixture`). Lot carries markers whole into\n  the site; Level Factory 0.265.0 hands them to Dispatch as `trigger` anchors when a brief turns gameplay events on.\n  Keyed on what the generator placed, so every fixture of a kind carries its hook in any building, and a new score\n  location adds rows, not code.\n\n### Tests\n- `tests/test_score_alarms.py` (new; fails on 0.288.0): every alarmed fixture in three banks has its hook, at its\n  slot, with its event; a hook sits in its room; the vocabulary is data and nothing more.\n\n## [0.288.0] - a bank\'s deposit vault is lined with boxes\n')], 'VERSION': [('lines 1-1', 'Deli Counter 0.288.0', 'Deli Counter 0.289.0')], 'build_freshness.py': [('lines 50-51', '    "deli_counter.py",      # the builder itself\n    "stairwell.py",         # stair geometry + ramp_foot_extension\n', '    "deli_counter.py",      # the builder itself\n    "score_alarms.py",      # a score\'s alarm markers, in the gameplay manifest a shell carries (0.289.0)\n    "stairwell.py",         # stair geometry + ramp_foot_extension\n')], 'deli_counter.py': [('lines 1487-1488', '        self._markers()\n        self._heist()\n', "        self._markers()\n        # after the markers and every slot: the score's alarm hooks (0.289.0)\n        self._score_alarms()\n        self._heist()\n"), ('lines 3282-3283', '\n    def _markers(self):\n', '\n    #: the score\'s alarm hooks (0.289.0): the table lives in `score_alarms`, which needs no Blender\n    def _score_alarms(self):\n        """One `alarm` marker per slot an `ALARM_FIXTURES` row names, at the slot\'s centre, in the innermost room on\n        its storey that holds it (or none), its event in `meta`. Lot carries a marker whole into the site and Level\n        Factory hands it to Dispatch as a `trigger` anchor. Returns the number written."""\n        import math\n        import score_alarms\n        H = float(self.s.story_height or 3.0)\n        rooms = self.gameplay.get("rooms") or []\n        n = 0\n        for s in self.slots:\n            row = next((r for r in score_alarms.ALARM_FIXTURES if s.get(r[0]) == r[1]), None)\n            if row is None:\n                continue\n            x, y, z = (float(v) for v in s["transform"]["translation"])\n            story = s.get("story")\n            story = int(story) if story is not None else int(math.floor((z + 1e-6) / H))\n            holding = [r for r in rooms if int(r.get("story", 0) or 0) == story\n                       and r["bounds"][0] <= x <= r["bounds"][2] and r["bounds"][1] <= y <= r["bounds"][3]]\n            room = min(holding, key=lambda r: (r["bounds"][2] - r["bounds"][0]) * (r["bounds"][3] - r["bounds"][1]),\n                       default=None)\n            name = "ALARM_%s" % s["slot_id"].upper()\n            self._empty(name, (x, y, z), self.MARKERS)\n            self.gameplay["markers"].append({\n                "name": name, "type": "alarm", "id": s["slot_id"], "x": x, "y": y, "z": z, "rot_z": 0.0,\n                "room": room["id"] if room else None,\n                "meta": {"event": row[2], "audible": row[3], "fixture": row[1]}})\n            n += 1\n        return n\n\n    def _markers(self):\n')], 'root_modules.txt': [('lines 62-63', 'roundtrip.py\nscout_model.py\n', 'roundtrip.py\nscore_alarms.py\nscout_model.py\n')]}
