NEW_FILES = {'score_alarms.py': '"""A score\'s alarm hooks: what fixture carries which gameplay event (Deli Counter 0.289.0, the factory\'s roadmap 323).\n\nPure, so the tests read it without Blender; `deli_counter._Builder._score_alarms` writes one `alarm` marker per slot a\nrow names.\n"""\n\n#: A SCORE\'S ALARM HOOKS (0.289.0, the factory\'s roadmap 323). The walker: "in the \'score\' location there should\n#: be gameplay events or something that doesn\'t mean much for level factory but is part of what would trigger\n#: police coming or stuff like that for the dispatch layer", and "they could mean nothing, but they could also be\n#: ingested/used by the gameplay layer". So a hook is DATA, not behaviour: where the fixture is, an event name, and\n#: one plain fact about the real object -- whether its alarm is audible. No heat, no timers, no response: those are\n#: the game\'s. Keyed on what the generator placed, so every fixture of a kind carries its hook, in any building:\n#: (key, value, event, audible) -- key is the slot\'s `role` or its `species`. A teller\'s holdup button is silent;\n#: a vault door\'s contact alarm sounds; an ATM\'s tamper alarm sounds. `score.cash_moved` is an event, not an alarm.\nALARM_FIXTURES = (\n    ("species", "teller_line", "alarm.panic_button", False),\n    ("role", "vault_door", "alarm.vault_door", True),\n    ("role", "safe_deposit_boxes", "alarm.deposit_drilled", False),\n    ("species", "drop_safe", "alarm.safe_opened", False),\n    ("species", "atm", "alarm.atm_tampered", True),\n    ("species", "cash_cart", "score.cash_moved", False),\n)\n', 'tests/test_score_alarms.py': '"""A score\'s alarm hooks (0.289.0, the factory\'s roadmap 323).\n\nThe walker: score locations should carry "gameplay events ... part of what would trigger police coming or stuff like\nthat for the dispatch layer" -- data a game may use or ignore. Every slot of an alarmed fixture writes one `alarm`\nmarker: where it is, its event, whether the real alarm is audible. FAILS ON 0.288.0, which writes none.\n"""\nimport json\nimport os\n\nimport score_alarms\n\nHERE = os.path.dirname(os.path.dirname(os.path.abspath(__file__)))\nBUILD = os.path.join(HERE, "build")\nROWS = score_alarms.ALARM_FIXTURES\n\n\ndef _built(name):\n    slots = json.load(open(os.path.join(BUILD, name + ".slots.json"), encoding="utf-8"))["slots"]\n    gp = json.load(open(os.path.join(BUILD, name + ".gameplay.json"), encoding="utf-8"))\n    return slots, gp\n\n\ndef _row(slot):\n    return next(((e, a, v) for k, v, e, a in ROWS if slot.get(k) == v), None)\n\n\ndef test_every_alarmed_fixture_in_a_bank_has_its_hook():\n    for name in ("bank_branch_a02", "bank_job", "bank_tower_a01"):\n        slots, gp = _built(name)\n        alarms = {m["id"]: m for m in gp["markers"] if m["type"] == "alarm"}\n        want = [s for s in slots if _row(s)]\n        assert want and len(alarms) == len(want), (name, len(alarms), len(want))\n        for s in want:\n            event, audible, fixture = _row(s)\n            m = alarms[s["slot_id"]]\n            assert m["meta"] == {"event": event, "audible": audible, "fixture": fixture}, (name, m)\n            assert [m["x"], m["y"], m["z"]] == [float(c) for c in s["transform"]["translation"]], (name, m)\n    _slots, gp = _built("bank_branch_a02")\n    events = [m["meta"]["event"] for m in gp["markers"] if m["type"] == "alarm"]\n    assert "alarm.panic_button" in events and "alarm.vault_door" in events\n    assert events.count("alarm.deposit_drilled") == 7\n\n\ndef test_a_hook_sits_in_its_room():\n    _slots, gp = _built("bank_branch_a02")\n    by = {m["meta"]["event"]: m for m in gp["markers"] if m["type"] == "alarm"}\n    assert by["alarm.deposit_drilled"]["room"] in ("vault", "vault_west", "vault_east")\n    assert by["alarm.panic_button"]["room"] is not None\n\n\ndef test_the_vocabulary_is_data_and_nothing_more():\n    """Each row is (key, value, event, audible): no heat, timer or response -- those are the game\'s."""\n    for key, value, event, audible in ROWS:\n        assert key in ("role", "species") and isinstance(value, str)\n        assert event.startswith(("alarm.", "score.")) and isinstance(audible, bool)\n    assert len({r[2] for r in ROWS}) == len(ROWS)\n'}


def _sha(text):
    return hashlib.sha256(text.encode("utf-8")).hexdigest()[:16]


def _read(name):
    """The file's LF text and whether it is CRLF on disk; refuses mixed endings and a file that is not the pinned one."""
    raw = (REPO / name).read_bytes()
    crlf, lf = raw.count(b"\r\n"), raw.count(b"\n")
    if crlf not in (0, lf):
        raise SystemExit("REFUSED: %s/%s has mixed line endings; nothing written" % (REPO.name, name))
    text = raw.decode("utf-8").replace("\r\n", "\n")
    if _sha(text) != PINS[name]:
        raise SystemExit("REFUSED: %s/%s is %s, not the %s this patch was written against; nothing written"
                         % (REPO.name, name, _sha(text), PINS[name]))
    return text, crlf > 0


def main():
    out = {}
    for name, edits in EDITS.items():
        text, crlf = _read(name)
        for what, old, new in edits:
            if text.count(old) != 1:
                raise SystemExit("REFUSED: %s/%s: the anchor at %s is there %d times; nothing written"
                                 % (REPO.name, name, what, text.count(old)))
            text = text.replace(old, new)
        out[name] = text.replace("\n", "\r\n") if crlf else text
    for name, text in WHOLE.items():
        _old, crlf = _read(name)
        out[name] = text.replace("\n", "\r\n") if crlf else text
    for name in NEW_FILES:
        if (REPO / name).exists():
            raise SystemExit("REFUSED: %s/%s exists already; nothing written" % (REPO.name, name))
    for name, text in out.items():
        (REPO / name).write_bytes(text.encode("utf-8"))
    for name, text in NEW_FILES.items():
        (REPO / name).parent.mkdir(parents=True, exist_ok=True)
        (REPO / name).write_bytes(text.encode("utf-8"))
    print("%s: %d files edited, %d written" % (REPO.name, len(out), len(NEW_FILES)))
    return 0


if __name__ == "__main__":
    sys.exit(main())
